CREATE OR REPLACE FUNCTION opening_windows(p_restaurant uuid,p_date date) RETURNS TABLE(win tstzrange) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE v_tz text; BEGIN SELECT r.timezone INTO v_tz FROM restaurants r WHERE r.id=p_restaurant; IF v_tz IS NULL OR EXISTS(SELECT 1 FROM special_closures sc WHERE sc.restaurant_id=p_restaurant AND sc.date=p_date) THEN RETURN; END IF; RETURN QUERY SELECT tstzrange((p_date+oh.opens) AT TIME ZONE v_tz,(p_date+oh.closes+CASE WHEN oh.closes<=oh.opens THEN interval '1 day' ELSE interval '0 day' END) AT TIME ZONE v_tz) FROM opening_hours oh WHERE oh.restaurant_id=p_restaurant AND NOT oh.is_closed AND oh.weekday=extract(isodow FROM p_date)::int-1; END $$;
